import { bindings, defineConfig, exports, triggers } from 'cf/config';

// Deployment identity for the cf CLI, generated by `cf migrate` from the
// previous configuration; CI compares the emitted Build Output with it.
// Jobs stay off until named in CRON_CONTROL_ENABLED_JOBS (legacy Worker ports
// also require CRON_CONTROL_WORKER_PROCESSORS selection); the
// CronLedger SQLite Durable Object records each job's attempts.
export default defineConfig({
  accountId: 'e8912e2867beecc673d171907bf09649',
  worker: {
    name: 'tuturuuu-cron-control',
    compatibilityDate: '2026-09-28',
    entrypoint: 'src/worker.ts',
    workersDev: false,
    previewUrls: false,
    observability: {
      enabled: true,
      headSamplingRate: 0.05,
      traces: { enabled: false, headSamplingRate: 0.05, persist: true },
      logs: { enabled: true, headSamplingRate: 0.05, invocationLogs: true },
    },
    triggers: [
      '* * * * *',
      '0 */12 * * *',
      '0 */6 * * *',
      '0 6 * * *',
      '*/10 * * * *',
      '*/15 * * * *',
      '17 3 * * *',
      '*/30 * * * *',
      '*/5 * * * *',
      // ai-studio-retention: 02:43 GMT+7.
      '43 19 * * *',
      // meet-attendance-retention: 01:17 GMT+7. The job stays disabled until
      // CRON_CONTROL_ENABLED_JOBS names it.
      '17 18 * * *',
    ].map((schedule) => triggers.scheduled({ schedule })),
    env: {
      WEB_ORIGIN: bindings.text('https://tuturuuu.com'),
      INFRASTRUCTURE_ORIGIN: bindings.text(
        'https://infrastructure.tuturuuu.com'
      ),
      INVENTORY_ORIGIN: bindings.text('https://inventory.tuturuuu.com'),
      PAY_ORIGIN: bindings.text('https://pay.tuturuuu.com'),
      TASKS_ORIGIN: bindings.text('https://tasks.tuturuuu.com'),
      CRON_CONTROL_ENABLED_JOBS: bindings.text(
        'database-cron-history-retention,ai-studio-retention,web-notification-batches,web-post-email-queue,web-report-automation,web-topic-announcements,web-deadline-reminders,finance-exchange-rates'
      ),
      // Cron Control is web's only scheduler (apps/web/vercel.json has no
      // crons). 'active' dispatches the five web-* jobs; 'off' stops only
      // those. finance-exchange-rates is not gated by it: drop its id above.
      CRON_CONTROL_WEB_MODE: bindings.text('active'),
      // Counts only until a reviewed change sets 'delete'; 'off' is the kill
      // switch. Any other value (including unset or padded) means off.
      AI_STUDIO_RETENTION_MODE: bindings.text('dry-run'),
      CRON_CONTROL_WORKER_PROCESSORS: bindings.text(''),
      TASKS_RECURRENCE_MODE: bindings.text('off'),
      // Read by the observability-cloudflare collector with the optional
      // CLOUDFLARE_ANALYTICS_API_TOKEN secret (Account Analytics Read).
      CLOUDFLARE_ACCOUNT_ID: bindings.text('e8912e2867beecc673d171907bf09649'),
      SUPABASE_URL: bindings.secret(),
      SUPABASE_SECRET_KEY: bindings.secret(),
      CRON_CONTROL_DELIVERY_TOKEN: bindings.secret(),
      CRON_CONTROL_OPERATOR_TOKEN: bindings.secret(),
      CRON_LEDGER: bindings.durableObject({
        worker: 'tuturuuu-cron-control',
        exportName: 'CronLedger',
      }),
    },
    exports: {
      CronLedger: exports.durableObject({ storage: 'sqlite' }),
    },
  },
});
